def main():
    assert len(NEW_200) == 200, f"Expected 200 new items, got {len(NEW_200)}"

    # Load existing first 60 items (idempotent)
    code = "global.window={};\n" + PKR_JS.read_text(encoding="utf-8") + "\nconsole.log(JSON.stringify(window.PKR_PRICES_GAME_DATA));"
    res = subprocess.run(["node", "-"], input=code, capture_output=True, text=True, encoding="utf-8", check=True)
    existing = json.loads(res.stdout)
    base_60 = existing[:60]
    assert len(base_60) == 60, f"Expected 60 base items, got {len(base_60)}"

    seen_ids = {x["id"] for x in base_60}
    appended = []
    for item_id, cat, emoji, title, price, unit, hint, breakdown in NEW_200:
        if item_id in seen_ids:
            raise ValueError(f"Duplicate item id: {item_id}")
        assert price > 0, f"Invalid price for {item_id}: {price}"
        seen_ids.add(item_id)
        appended.append({
            "id": item_id,
            "title": title,
            "category": cat,
            "categoryLabel": CAT_LABELS[cat],
            "icon": "fa-coins",
            "emoji": emoji,
            "pricePkr": price,
            "unit": unit,
            "hint": hint,
            "breakdown": breakdown,
        })

    combined = base_60 + appended
    header = (
        "/**\n"
        f" * Guess the Price & Salary in Pakistani Rupees (PKR) — Expanded Game Dataset\n"
        f" * {len(combined)} Realistic 2025–2026 Benchmarks across 8 Categories\n"
        " */\n"
        "window.PKR_PRICES_GAME_DATA = "
    )
    PKR_JS.write_text(header + json.dumps(combined, ensure_ascii=False, indent=2) + ";\n", encoding="utf-8")

    cats = Counter(x["category"] for x in combined)
    print(f"Successfully wrote {len(combined)} total PKR items ({len(appended)} newly added)!")
    print("Category breakdown:", dict(cats))


if __name__ == "__main__":
    main()
